"""Pack all attribution classes into one short receipt; no rerun."""
import argparse,hashlib,json,pathlib

def main():
 p=argparse.ArgumentParser();p.add_argument('--work-dir',type=pathlib.Path,required=True);p.add_argument('--output',type=pathlib.Path,required=True);a=p.parse_args();d=a.work_dir
 def file(p):return {'path':str(p),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
 base=json.loads((d/'g4-attribution.json').read_text());classes=json.loads((d/'g4-classes.json').read_text());replay=json.loads((d/'g4/summary.json').read_text());expected={r['name']:json.loads((d/'g4'/(r['name']+'.json')).read_text())['cases'][0]['input_sha256'] for r in replay['cases']}
 inventory=[file(p) for sub in ['attribution','classes'] for p in sorted((d/sub).iterdir()) if p.is_file()];inventory.extend(file(d/p) for p in ['g4-attribution.json','g4-classes.json']);ip=d/'g4-attribution-inventory.json';ip.write_text(json.dumps(inventory,indent=2)+'\n')
 columns=['core','precision','gap_ld','raw_normal_Q','propagated_normal','reconstruction_defect','F_max_norm','F_Fro','F_max_over_u','F_max_over_u_operation_norm_sum','normalized_source_Fro','normal_amplification_over_F_Fro'];keys=['core','precision','actual_gap_against_ld_reference','raw_normal_Q_norm','propagated_normal_norm','normal_reconstruction_discrepancy','max_local_residual_norm','local_residual_fro','max_local_residual_over_u','max_local_residual_over_u_operation_norm_sum','normalized_source_fro','normal_amplification_over_residual_fro'];rows=[]
 for case in base['cases']+classes['cases']:
  assert case['input_sha256']==expected[case['name']]
  row={k:v for k,v in case.items() if k!='controls'};row.setdefault('method','upstream_yx=dev');row['controls']=[[z[k] for k in keys] for z in case['controls']]
  row['binary64_quality']=[{'core':z['core'],'reference_noise_over_normal':case['reference_double_vs_ld_projector_gap']/z['raw_normal_Q_norm'],'reconstruction_over_normal':z['normal_reconstruction_discrepancy']/z['raw_normal_Q_norm'],'reference_noise_over_kernel_change':case['reference_double_vs_ld_projector_gap']/case['kernel_normal_Q_difference'],'reconstruction_over_kernel_change':z['normal_reconstruction_discrepancy']/case['kernel_normal_Q_difference']} for z in case['controls'] if z['precision']=='double']
  row['binary64_quality_max_ratios']=[max(q[k] for q in row['binary64_quality']) for k in ['reference_noise_over_normal','reconstruction_over_normal','reference_noise_over_kernel_change','reconstruction_over_kernel_change']];del row['binary64_quality'];rows.append(row)
 libs=base['cases'][0]['controls'][0]['runtime']['libraries'];ans={'status':'DEVELOPER_ATTRIBUTION_REVIEW_PENDING_L7_STOP','rules_head':'bb67c1ee830d468fa33007e15008d5574d00ccf4','scope':'Two actual G4 rows; all5 distinct arithmetic classes. No suite.','longdouble_nmant':base['longdouble_nmant'],'helper_executed_yx_sha256':base['code_sha256'],'class_code_sha256':classes['code_sha256'],'helper_class_sha256':classes['helper_sha256'],'inventory':file(ip),'external_receipts':[file(d/p) for p in ['g4-attribution.json','g4-classes.json']],'loaded_libraries':[{k:v for k,v in z.items() if k in ['filepath','sha256','version','internal_api']} for z in libs],'quality_max_columns':['reference_noise_over_normal','reconstruction_over_normal','reference_noise_over_kernel_change','reconstruction_over_kernel_change'],'control_columns':columns,'cases':rows,'limits':['Original replay mismatches/thresholds preserved; no automatic G4 PASS.','Historical Q/H/dispatch absent. Historical trajectory not reconstructed/enclosed.','Longdouble inverse reconstructs binary64 normal drift; extended-run reconstruction is precision limited.','Developer execution only; distinct review/root disposition needed.']};a.output.write_text(json.dumps(ans,separators=(',',':'))+'\n');assert a.output.stat().st_size<16384
if __name__=='__main__':main()
